{"implementation": "import json

def solve(case):
    # Validate required fields
    if 'edges' not in case or not isinstance(case['edges'], list):
        raise ValueError('Missing or invalid "edges"')
    if 'communities' not in case or not isinstance(case['communities'], dict):
        raise ValueError('Missing or invalid "communities"')
    if 'resolution' not in case:
        raise ValueError('Missing "resolution"')

    edges = case['edges']
    communities = case['communities']
    resolution = float(case['resolution'])

    # Build adjacency and degree
    adj = {}
    for u, v, w in edges:
        if not isinstance(w, (int, float)):
            raise ValueError('Edge weight must be numeric')
        w = float(w)
        adj.setdefault(u, {})[v] = adj[u].get(v, 0.0) + w
        adj.setdefault(v, {})[u] = adj[v].get(u, 0.0) + w

    # Ensure all nodes from communities are in adjacency (isolated nodes)
    for node in communities:
        if node not in adj:
            adj[node] = {}

    # Node order: sorted by node ID (string)
    nodes = sorted(adj.keys())

    # Current assignment (copy so we don't mutate input)
    assign = dict(communities)

    moves = []
    changed = True
    while changed:
        changed = False
        for node in nodes:
            cur_comm = assign[node]
            # Compute sum(w - gamma) for each neighboring community
            gain_map = {}
            for nb, w in adj[node].items():
                nb_comm = assign[nb]
                gain_map[nb_comm] = gain_map.get(nb_comm, 0.0) + (w - resolution)
            # Also consider staying: current community may have no neighbors
            if cur_comm not in gain_map:
                gain_map[cur_comm] = 0.0
            # Current contribution
            cur_gain = gain_map.get(cur_comm, 0.0)
            best_gain = None
            best_comm = None
            for comm, g in gain_map.items():
                delta = g - cur_gain
                if delta > 1e-12:  # strictly positive (tolerance for floating point)
                    if best_gain is None or delta > best_gain or (abs(delta - best_gain) < 1e-12 and comm < best_comm):
                        best_gain = delta
                        best_comm = comm
            if best_comm is not None:
                assign[node] = best_comm
                moves.append({'from': cur_comm, 'node': node, 'to': best_comm})
                changed = True

    # Ensure every node has a community (should be, but just in case)
    for node in nodes:
        if node not in assign:
            assign[node] = ''  # fallback (should not happen)

    result = {
        'communities': assign,
        'moves': moves
    }
    return result
